package service;import java.nio.file.*;import java.io.*;import java.nio.file.attribute.*;public class ReportGenerator{public static String generate(){long deposits=0,withdrawals=0;StringBuilder b=new StringBuilder("MINIBANK END-OF-DAY REPORT\n");Path dir=Path.of("data");try{if(Files.exists(dir))try(DirectoryStream<Path>s=Files.newDirectoryStream(dir,"*.log")){for(Path p:s){try(BufferedReader r=Files.newBufferedReader(p)){String line;while((line=r.readLine())!=null){String[] a=line.split("\\|");if(a.length>=3){long v=Long.parseLong(a[2]);if(a[1].equals("DEPOSIT"))deposits+=v;if(a[1].equals("WITHDRAW"))withdrawals+=v;}}}BasicFileAttributes at=Files.readAttributes(p,BasicFileAttributes.class);b.append(p.getFileName()).append(" size=").append(at.size()).append(" modified=").append(at.lastModifiedTime()).append('\n');}}b.append("Total deposits: ").append(deposits).append("\nTotal withdrawals: ").append(withdrawals);Files.writeString(dir.resolve("report.txt"),b.toString());}catch(Exception e){b.append("\nReport error: ").append(e.getMessage());}return b.toString();}}
